import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array<{ status: string, number: string, customerId: string, dueDate: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} - sorted by daysOverdue descending
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      const due = balanceDue(inv);
      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get VAT summary over invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} - sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const lineTotal = line.qty * line.unitPrice;
        const lineDiscountPercent = line.discountPercent ?? 0;
        const lineDiscount = Math.round(lineTotal * lineDiscountPercent / 100);
        const discountedAmount = lineTotal - lineDiscount;
        const lineVat = roundCents(discountedAmount * line.vatRate / 100);

        const rate = line.vatRate;
        if (!vatMap.has(rate)) {
          vatMap.set(rate, { base: 0, vat: 0 });
        }

        const entry = vatMap.get(rate);
        entry.base += discountedAmount;
        entry.vat += lineVat;
      });
    });

  // Convert map to array and sort by rate descending
  const result = Array.from(vatMap.entries())
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);

  return result;
}

/**
 * Calculate late fee for an invoice.
 * Late fee is 0.04% of the amount due per day overdue, 0 if not overdue.
 * @param {{ dueDate: string, status: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {number} - late fee in cents, rounded to nearest cent
 */
export function lateFee(invoice, asOf) {
  // If invoice is not issued or partially paid, no late fee
  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // If not overdue, return 0
  if (daysOverdue <= 0) {
    return 0;
  }

  // Get amount due
  const due = balanceDue(invoice);

  // Calculate fee: 0.04% per day = 0.0004 per day
  const fee = due * daysOverdue * 0.0004;

  // Round to nearest cent
  return Math.round(fee);
}

