9	  assert.deepEqual(result, []);
10	});
11	
12	test('overdueInvoices: returns empty array when no overdue invoices', () => {
13	  const invResult = createInvoice({
14	    customerId: 'C-002',
15	    issueDate: '2026-10-07',
16	    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
17	    terms: 'NET30',
18	  });
19	  assert.ok(invResult.ok);
20	  const issued = issueInvoice(invResult.value, []);
21	  assert.ok(issued.ok);
22	
23	  // Invoice due date is 2026-11-06, check as of 2026-11-05
24	  const result = overdueInvoices([issued.value], '2026-11-05');
25	  assert.deepEqual(result, []);
26	});
27	
28	test('overdueInvoices: includes invoice that is one day overdue', () => {
29	  const invResult = createInvoice({
30	    customerId: 'C-002',
31	    issueDate: '2026-10-07',
32	    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
33	    terms: 'NET30',
34	  });
35	  assert.ok(invResult.ok);
36	  const issued = issueInvoice(invResult.value, []);
37	  assert.ok(issued.ok);
38	
39	  // Invoice due date is 2026-11-06, check as of 2026-11-07
40	  const result = overdueInvoices([issued.value], '2026-11-07');
41	  assert.equal(result.length, 1);
42	  assert.equal(result[0].number, issued.value.number);
