    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Due date is 2026-11-06, check on 2026-11-07 (1 day overdue)
  // Total due: 91960, fee: 91960 * 1 * 0.0004 = 36.784 ≈ 37
  const fee = lateFee(issued.value, '2026-11-07');
  assert.equal(fee, 37);
});

