test('dashboard: top customers by due amount', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv1Result.ok);
  const inv1 = issueInvoice(inv1Result.value, []);
  assert.ok(inv1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(inv2Result.ok);
  const inv2 = issueInvoice(inv2Result.value, [inv1.value.number]);
  assert.ok(inv2.ok);

  const inv3Result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 4 }],
  });
  assert.ok(inv3Result.ok);
  const inv3 = issueInvoice(inv3Result.value, [inv1.value.number, inv2.value.number]);
  assert.ok(inv3.ok);

  const result = dashboard([inv1.value, inv2.value, inv3.value], '2026-12-31');

  // C-001 (gold, 5% discount): 9500 - 475 + 1895 = 10920
  // C-002 (standard): 76000 + 15960 = 91960
  // C-003 (silver, 2.5% discount): 38000 - 950 + 7781 = 44831
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert.equal(result.topCustomers[0].due, 91960);
  assert.equal(result.topCustomers[1].customerId, 'C-003');
  assert.equal(result.topCustomers[1].due, 44831);
  assert.equal(result.topCustomers[2].customerId, 'C-001');
  assert.equal(result.topCustomers[2].due, 10920);
});

test('dashboard: top customers returns at most 3', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const invResult = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    });
    assert.ok(invResult.ok);
    const issued = issueInvoice(invResult.value, invoices.map((inv) => inv.number));
    assert.ok(issued.ok);
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2026-12-31');

  assert.equal(result.topCustomers.length, 3);
  assert.ok(result.topCustomers[0].due >= result.topCustomers[1].due);
  assert.ok(result.topCustomers[1].due >= result.topCustomers[2].due);
});

